'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brl=(v)=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const localISO=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const localPlusDays=(n)=>{let d=new Date(localISO()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
const fdate=(s)=>s?String(s).slice(0,10).split('-').reverse().join('/'):'—';
const short=(n)=>String(n||'').trim().split(/\s+/).slice(0,2).map(a=>a[0]?.toUpperCase()).join('')||'CL';
const phone=(p)=>String(p||'').replace(/\D/g,'');
const icon={chart:'◫',clients:'♧',clock:'◷',money:'◈',plans:'▤',star:'✦'};
const views={dashboard:'Visão geral',clients:'Clientes',reminders:'Vencimentos',payments:'Financeiro',reports:'Relatórios',panels:'Integrações',plans:'Planos & preços',settings:'Configurações',team:'Equipe',activity:'Histórico',leads:'Funil comercial',interactions:'Atendimentos',invoices:'Faturas',campaigns:'Campanhas',referrals:'Indicações',security:'Segurança 2FA'};
let state={csrf:'',me:null,view:'dashboard',clients:[],plans:[],panels:[],payments:[],dashboard:null,reminders:[],activity:[],settings:null,staff:[],filter:'all',query:''};
let remoteState={panelId:null,session:null,busy:false};
const api=async (p,opts={})=>{const res=await fetch('/api'+p,{credentials:'same-origin',...opts,headers:{...(opts.body?{'content-type':'application/json'}:{}),...(state.csrf?{'x-csrf-token':state.csrf}:{}),...(opts.headers||{})}});let data=await res.json().catch(()=>({}));if(!res.ok){if(res.status===401&&p!=='/login'){showAuth(true);}throw Error(data.error||'Ocorreu um erro');}return data;};
const request=(p,method,data)=>api(p,{method,body:JSON.stringify(data)});
function toast(msg,error=false){let n=document.createElement('div');n.className='toast'+(error?' error':'');n.textContent=(error?'⚠ ':'✦ ')+msg;$('#toast-area').append(n);setTimeout(()=>n.remove(),4800);}
function showAuth(initialized=true){$('#app').classList.add('hide');$('#auth').classList.remove('hide');$('#setup-extra').classList.toggle('hide',initialized);$('#auth-title').innerHTML=initialized?'Seu negócio. <em>No controle.</em>':'A sua nova era <em>começa aqui.</em>';$('#auth-sub').textContent=initialized?'Entre com suas credenciais para continuar.':'Crie sua primeira conta administradora e prepare seu workspace.';$('#auth-submit').innerHTML=initialized?'Entrar na plataforma <span>↗</span>':'Criar minha plataforma <span>↗</span>';$('#auth-form').dataset.mode=initialized?'login':'setup';}
async function boot(){try{const init=await api('/bootstrap');if(init.initialized){try{let me=await api('/me');await enter(me);return;}catch{showAuth(true);}}else showAuth(false);}catch(e){showAuth(true);toast('Não foi possível conectar ao servidor: '+e.message,true);}}
async function enter(me){state.me=me;state.csrf=me.csrf;$('#auth').classList.add('hide');$('#app').classList.remove('hide');$('#avatar').textContent=short(me.name).slice(0,1);await refresh();route('dashboard');}
async function refresh(){const [clients,plans,panels,settings,db,reminders,payments]=await Promise.all([api('/clients'),api('/plans'),api('/panels'),api('/settings'),api('/dashboard'),api('/reminders'),api('/payments')]);Object.assign(state,{clients:clients.clients,plans:plans.plans,panels:panels.panels,settings,dashboard:db,reminders:reminders.reminders,payments:payments.payments});$('#business-label').textContent=settings.business_name;$('#nav-client-count').textContent=state.clients.length;$('#nav-due-count').textContent=state.reminders.length;$('#alert-dot').classList.toggle('hide',!state.reminders.length);}
async function afterSave(message){await refresh();route(state.view);if(message)toast(message);}
function route(name){if(!views[name])name='dashboard';state.view=name;$('#breadcrumb').textContent=views[name];$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===name));$('#sidebar').classList.remove('open');$('#veil').classList.remove('open');const c=$('#content');c.style.animation='none';void c.offsetHeight;c.style.animation='';const render={dashboard:renderDashboard,clients:renderClients,reminders:renderReminders,payments:renderPayments,reports:renderReports,panels:renderPanels,plans:renderPlans,settings:renderSettings,team:renderTeam,activity:renderActivity,leads:()=>growView('leads'),interactions:()=>growView('interactions'),invoices:()=>growView('invoices'),campaigns:()=>growView('campaigns'),referrals:()=>growView('referrals'),security:()=>growView('security')}[name];render();}
function title(label,heading,subtitle,buttons=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(label)}</div><h1>${esc(heading)}</h1><p>${esc(subtitle)}</p></div><div class="header-actions">${buttons}</div></div>`;}
function btn(txt,action,type='ghost',extra=''){return `<button class="btn ${type}" data-action="${action}" ${extra}>${txt}</button>`;}
function status(c){let overdue=c.days_left<0&&['active','trial'].includes(c.status);return overdue?'<span class="status expired">Vencido</span>':{active:'<span class="status active">Ativo</span>',trial:'<span class="status trial">Teste</span>',paused:'<span class="status paused">Pausado</span>',canceled:'<span class="status canceled">Cancelado</span>'}[c.status]||'';}
function smallDue(c){if(c.days_left<0)return `<span style="color:#ff8da9">${Math.abs(c.days_left)} dia(s) de atraso</span>`;if(c.days_left===0)return '<span style="color:#ffc287">Vence hoje</span>';return `${c.days_left} dia(s) restantes`;}
function initials(name,i=0){return `<span class="circle-avatar ${i%3===1?'green':i%3===2?'pink':''}">${esc(short(name))}</span>`;}
function renderDashboard(){let d=state.dashboard;$('#content').innerHTML=title('✦ SEU CENTRO DE CONTROLE',`Olá, ${state.me.name.split(' ')[0]}! 👋`,'Sua operação em tempo real. Tudo o que importa, em um só lugar.',btn('↗ Exportar dados','export')+btn('＋ Novo cliente','new-client','primary'))+`<div class="grid4">
<div class="kpi-card featured"><div class="kpi-top">Total de clientes <span class="kpi-icon">♧</span></div><strong>${d.total}</strong><div class="kpi-foot">Base cadastrada no sistema</div></div>
<div class="kpi-card"><div class="kpi-top">Assinaturas ativas <span class="kpi-icon" style="color:#58e7c6;background:#1e5a5050">✓</span></div><strong>${d.active}</strong><div class="kpi-foot"><b>●</b> Dentro do vencimento</div></div>
<div class="kpi-card"><div class="kpi-top">Vencidos <span class="kpi-icon" style="color:#ff9daf;background:#7f2b4850">◷</span></div><strong>${d.overdue}</strong><div class="kpi-foot">Precisam de atenção</div></div>
<div class="kpi-card"><div class="kpi-top">Recebido este mês <span class="kpi-icon" style="color:#f8c684;background:#744b2d55">◈</span></div><strong>${brl(d.revenue_month)}</strong><div class="kpi-foot">Pagamentos registrados</div></div></div>
<div class="two-col"><section class="panel-card"><div class="section-row"><div><h2>Visão financeira</h2><p>Recebimentos dos últimos 6 meses</p></div><span class="chart-legend">Receita</span></div>${chart(d.chart)}</section><section class="panel-card"><div class="section-row"><div><h2>Próximos vencimentos</h2><p>${d.upcoming} a vencer em 7 dias · ${d.overdue} atrasados</p></div><button class="link-btn" data-view="reminders">Ver todos ↗</button></div><div class="due-list">${d.due.length?d.due.map((c,i)=>`<div class="due-item">${initials(c.name,i)}<div class="due-item-info"><strong>${esc(c.name)}</strong><small>${esc(c.plan_name||'Plano personalizado')} · ${fdate(c.due_date)}</small></div><span class="due-date">${smallDue(c)}</span></div>`).join(''):`<div class="empty" style="padding:25px"><div class="empty-icon">✓</div><h3>Tudo em dia!</h3><p>Sem vencimentos críticos no momento.</p></div>`}</div></section></div>
<section class="panel-card mt20"><div class="section-row"><div><h2>Clientes recentes</h2><p>Novos cadastros da sua operação</p></div><button class="link-btn" data-view="clients">Abrir clientes ↗</button></div>${clientTable(d.recent,false)}</section>
<div class="banner mt20"><div><small>✦ CLYSTRIA INSIGHTS</small><h2>Antecipe renovações, cresça com previsibilidade.</h2><p>Automatize a organização dos vencimentos e conecte seus painéis usando integrações autorizadas.</p></div>${btn('Configurar lembretes ↗','go-reminders','primary')}<div class="banner-glow">✧</div></div>`;}
function chart(data){const max=Math.max(10,...data.map(d=>d.value)),pts=data.map((d,i)=>[40+i*98,175-(d.value/max)*142]);const line=pts.map(([x,y])=>x+','+y).join(' ');const area='M '+pts[0][0]+' 175 L '+pts.map(a=>a.join(' ')).join(' L ')+' L '+pts.at(-1)[0]+' 175 Z';return `<div class="chart-wrap"><svg viewBox="0 0 580 192" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#8170FF" stop-opacity=".42"/><stop offset="1" stop-color="#8170FF" stop-opacity="0"/></linearGradient></defs>${[40,85,130,175].map(y=>`<line x1="25" y1="${y}" x2="565" y2="${y}" stroke="#333a56" stroke-dasharray="3 7"/>`).join('')}<path d="${area}" fill="url(#area)"/><polyline points="${line}" fill="none" stroke="#8b7bff" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/>${pts.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5" fill="#b7a9ff" stroke="#171c35" stroke-width="3"/>`).join('')}</svg></div><div class="chart-axis">${data.map(x=>`<span>${new Date(x.month+'-10T12:00:00').toLocaleDateString('pt-BR',{month:'short'})}</span>`).join('')}</div>`;}
function clientTable(list,actions=true){if(!list.length)return `<div class="empty"><div class="empty-icon">♧</div><h3>Nenhum cliente por aqui</h3><p>Comece adicionando seu primeiro assinante.</p></div>`;return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>Login</th><th>Vencimento</th><th>Plano</th><th>Valor</th><th>Status</th>${actions?'<th>Ações</th>':''}</tr></thead><tbody>${list.map((c,i)=>`<tr><td><div class="client-cell">${initials(c.name,i)}<div><strong>${esc(c.name)}</strong><small>${esc(c.phone||c.email||'Sem contato')}</small></div></div></td><td>${esc(c.username||'—')}</td><td>${fdate(c.due_date)}<small style="display:block;margin-top:4px;color:#8090ae">${smallDue(c)}</small></td><td>${esc(c.plan_name||'Personalizado')}</td><td>${brl(c.price)}</td><td>${status(c)}</td>${actions?`<td><div class="table-actions"><button title="Editar" class="action-dot" data-action="edit-client" data-id="${c.id}">✎</button><button title="Renovar" class="action-dot" data-action="renew-client" data-id="${c.id}">↻</button><button title="Consentimento" class="action-dot" data-action="grow-consent" data-id="${c.id}">✉</button></div></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function filtered(){let a=state.clients.filter(c=>{let f=state.filter;let ok=f==='all'||(f==='overdue'&&['active','trial'].includes(c.status)&&c.days_left<0)||(f==='soon'&&['active','trial'].includes(c.status)&&c.days_left>=0&&c.days_left<=7)||(f==='active'&&c.status==='active'&&c.days_left>=0)||(f==='paused'&&['paused','canceled','trial'].includes(c.status));return ok&&(!state.query||[c.name,c.phone,c.username,c.email].some(v=>String(v||'').toLowerCase().includes(state.query.toLowerCase())));});return a;}
function renderClients(){let filters=[['all','Todos'],['active','Ativos'],['soon','Próximos'],['overdue','Vencidos'],['paused','Outros']];$('#content').innerHTML=title('BASE DE ASSINANTES','Gestão de clientes','Organize seus assinantes, credenciais e renovações em um único fluxo.',btn('↓ Importar CSV','import')+btn('↓ Exportar','export')+btn('＋ Novo cliente','new-client','primary'))+`<div class="panel-card"><div class="filterbar"><div class="searchbox">⌕ <input id="search" placeholder="Buscar por nome, telefone ou login..." value="${esc(state.query)}" autocomplete="off"></div><div class="filterchips">${filters.map(([v,l])=>`<button class="chip ${state.filter===v?'active':''}" data-filter="${v}">${l}</button>`).join('')}</div></div><div id="clients-table">${clientTable(filtered())}</div><p class="helper-text">${state.clients.length} clientes cadastrados • ${filtered().length} resultados encontrados</p></div>`;$('#search').addEventListener('input',e=>{state.query=e.target.value;$('#clients-table').innerHTML=clientTable(filtered());});}
function renderReminders(){let a=state.reminders;$('#content').innerHTML=title('AUTOMAÇÃO & RELACIONAMENTO','Central de vencimentos','Lembretes organizados, comunicação rápida e nenhuma renovação esquecida.',btn('⚙ Ajustar mensagens','go-settings')+btn('＋ Novo cliente','new-client','primary'))+`<div class="banner"><div><small>◷ RADAR DE VENCIMENTOS</small><h2>${a.length} clientes precisam de atenção</h2><p>Abra o WhatsApp com mensagem pronta. O envio acontece somente quando você confirma no aplicativo de mensagens.</p></div><div class="banner-glow">◷</div></div><section class="panel-card"><div class="section-row"><div><h2>Fila de lembretes</h2><p>Organizados por urgência e data de vencimento</p></div><span class="status warning">${a.length} pendentes</span></div>${a.length?a.map(c=>`<div class="reminder-card">${initials(c.name)}<div class="reminder-body"><h3>${esc(c.name)} <span style="font-weight:400;color:#8e9aba">· ${esc(c.username)}</span></h3><p>Vence ${fdate(c.due_date)} • ${smallDue(c)} • ${brl(c.price)}</p></div><div class="reminder-actions">${btn('WhatsApp ↗','whatsapp','mint',`data-id="${c.id}"`)}${btn('Renovar','renew-client','ghost',`data-id="${c.id}"`)}</div></div>`).join(''):`<div class="empty"><div class="empty-icon">✦</div><h3>Agenda em dia</h3><p>Quando houver vencimentos, eles aparecerão aqui automaticamente.</p></div>`}</section><div class="callout mt20"><b>Automação de e-mail:</b> disponível com SMTP configurado e rotina agendada no servidor. Mensagens pelo WhatsApp dependem de ação manual ou integração oficial adicional; não são disparadas automaticamente neste pacote.</div>`;}
function renderPayments(){let total=state.payments.reduce((s,p)=>s+p.amount,0);let month=state.payments.filter(p=>p.paid_at.startsWith(new Date().toLocaleDateString('sv-SE',{timeZone:'America/Sao_Paulo'}).slice(0,7))).reduce((s,p)=>s+p.amount,0);$('#content').innerHTML=title('CONTROLE FINANCEIRO','Seu financeiro, organizado','Registre pagamentos, acompanhe recebimentos e controle as renovações.',btn('↓ Exportar clientes','export')+btn('＋ Registrar pagamento','new-payment','primary'))+`<div class="grid4" style="grid-template-columns:repeat(auto-fit,minmax(190px,1fr))"><div class="kpi-card featured"><div class="kpi-top">Total recebido <span class="kpi-icon">◈</span></div><strong>${brl(total)}</strong><div class="kpi-foot">Todo o histórico</div></div><div class="kpi-card"><div class="kpi-top">Neste mês <span class="kpi-icon">↗</span></div><strong>${brl(month)}</strong><div class="kpi-foot">Pagamentos lançados</div></div><div class="kpi-card"><div class="kpi-top">Receita recorrente estimada <span class="kpi-icon">✦</span></div><strong>${brl(state.dashboard.expected_mrr)}</strong><div class="kpi-foot">Soma dos valores dos clientes ativos</div></div></div><section class="panel-card mt20"><div class="section-row"><div><h2>Histórico de recebimentos</h2><p>Registros manuais e renovações</p></div></div>${state.payments.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>Descrição</th><th>Forma</th><th>Data</th><th>Valor</th><th>Status</th></tr></thead><tbody>${state.payments.map(p=>`<tr><td><strong>${esc(p.client_name)}</strong></td><td>${esc(p.description||'Pagamento')}</td><td>${esc(p.method.toUpperCase())}</td><td>${fdate(p.paid_at)}</td><td>${brl(p.amount)}</td><td><span class="status paid">Recebido</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-icon">◈</div><h3>Sem recebimentos ainda</h3><p>Registre um pagamento ou renove um cliente para começar.</p></div>`}</section>`;}
function renderReports(){let d=state.dashboard,active=state.clients.filter(x=>x.status==='active').length,panelCounts={};for(let x of state.clients){let name=x.panel_name||'Sem painel';panelCounts[name]=(panelCounts[name]||0)+1;}let byPlan={};for(let x of state.clients){let name=x.plan_name||'Sem plano';byPlan[name]=(byPlan[name]||0)+1;}let totals=[['Ativos',state.clients.filter(x=>x.days_left>=0&&x.status==='active').length],['Em atraso',d.overdue],['Testes',state.clients.filter(x=>x.status==='trial').length],['Pausados/cancelados',state.clients.filter(x=>['paused','canceled'].includes(x.status)).length]];function bars(data){let top=Math.max(1,...data.map(x=>x[1]));return data.map(([label,value])=>`<div class="statline"><span>${esc(label)}</span><div class="bar"><i style="width:${Math.round(value/top*100)}%"></i></div><strong>${value}</strong></div>`).join('');}$('#content').innerHTML=title('INTELIGÊNCIA DE NEGÓCIO','Relatórios & insights','Enxergue os números reais da sua operação e tome decisões mais rápidas.',btn('↓ Exportar dados','export'))+`<div class="grid4"><div class="kpi-card featured"><div class="kpi-top">Base de clientes<span class="kpi-icon">♧</span></div><strong>${d.total}</strong><div class="kpi-foot">Assinantes registrados</div></div><div class="kpi-card"><div class="kpi-top">Taxa de ativos<span class="kpi-icon">◈</span></div><strong>${d.total?Math.round(d.active/d.total*100):0}%</strong><div class="kpi-foot">Ativos e em dia</div></div><div class="kpi-card"><div class="kpi-top">Em risco<span class="kpi-icon">◷</span></div><strong>${d.overdue+d.upcoming}</strong><div class="kpi-foot">Atrasados + vencendo</div></div><div class="kpi-card"><div class="kpi-top">Receita no mês<span class="kpi-icon">↗</span></div><strong>${brl(d.revenue_month)}</strong><div class="kpi-foot">Recebimento realizado</div></div></div><div class="grid-side mt20"><section class="panel-card"><div class="section-row"><h2>Distribuição por situação</h2></div>${bars(totals)}</section><section class="panel-card"><div class="section-row"><h2>Distribuição por planos</h2></div>${bars(Object.entries(byPlan))||'<p class="muted">Sem dados</p>'}</section></div><section class="panel-card mt20"><div class="section-row"><h2>Clientes por painel</h2></div>${bars(Object.entries(panelCounts))||'<p class="muted">Sem dados</p>'}</section>`;}
function renderPanels(){
 const panels=state.panels;
 $('#content').innerHTML=title('INTEGRAÇÕES EXTERNAS','Conectar seus painéis','Cadastre URL, usuário e senha. Experimente a leitura pela interface real no Chromium da VPS, sem API pública.',btn('↓ Importar arquivo','import')+btn('◉ Testar Chromium','browser-check')+btn('＋ Conectar painel','new-panel','primary'))+
 `<div class="banner"><div><small>✦ CENTRAL DE SINCRONIZAÇÃO</small><h2>Uma carteira de clientes. Vários painéis.</h2><p>Importe clientes, planos e vencimentos sem duplicidade. A sincronização automática pode ser executada a cada hora enquanto o servidor estiver funcionando.</p></div><div class="banner-glow">⇆</div></div>
 <div class="cards-grid"><div class="mini-card"><div class="mini-icon">🔐</div><h3>URL + usuário + senha</h3><p>O Clystria pode abrir um navegador Chromium na VPS para entrar no site do fornecedor e consultar a lista de clientes exibida.</p><small>Senhas criptografadas no PHP; sessão isolada</small></div>
 <div class="mini-card"><div class="mini-icon">⟳</div><h3>Leitura autorizada</h3><p>Consulta login, vencimento e demais campos apresentados na página, com limite de páginas e detecção de erros.</p><small>Não apaga clientes por ausência na resposta</small></div>
 <div class="mini-card"><div class="mini-icon">🌐</div><h3>Chromium em servidor</h3><p>O navegador remoto identifica telas de login e tabelas de clientes. Caso a Cloudflare solicite um desafio, o processo informa o bloqueio em vez de simular sucesso.</p><small>Sem extensão no celular nem navegador embutido</small></div></div>
 <div class="section-row mt28"><h2>Suas conexões</h2><span class="muted small">${panels.length} painéis</span></div>
 <div class="cards-grid">${panels.length?panels.map(p=>{const browser=p.auth_mode==='browser',ok=!browser&&p.last_status==='ok',failed=!browser&&String(p.last_status||'').startsWith('error:'),text=browser?'◷ Login pelo navegador':ok?'● Sincronizado':failed?'● Erro de conexão':'◷ Aguardando validação';return `<div class="mini-card"><div class="mini-icon">${p.kind==='sigma'?'◈':p.kind==='painelfoda'?'✦':'⌘'}</div><h3>${esc(p.name)}</h3><p>${esc(p.kind.toUpperCase())} · <span class="panel-status" style="color:${failed?'#FF99A9':ok?'#79E3C3':'#CBBEFD'}">${text}</span></p><div class="line-details">${esc(p.url)}</div><p class="helper-text">Autenticação: ${browser?'Apenas abrir no navegador':p.auth_mode==='remote_browser'?'Chromium na VPS':p.auth_mode==='token'?'Token de API':'Usuário e senha'} · ${browser?'Importação pelo arquivo exportado':p.auto_sync?'Sincronização por API ativada':'Sincronização manual por API'}</p>${p.login_user?`<p class="helper-text">Usuário: ${esc(p.login_user)}</p>`:''}${failed?`<div class="inline-notice" style="color:#FF99A9">${esc(p.last_status.slice(7))}${p.kind==='sigma'&&/404|rota de/i.test(p.last_status)?'<p style="margin-top:8px;color:#CFD4E8">O login pelo navegador não fornece uma API ao Clystria. Peça ao fornecedor Sigma a rota oficial de autenticação e consulta de clientes, ou uma chave de API autorizada. Edite a conexão nas configurações avançadas.</p>':''}</div>`:''}<div class="mini-bottom mt20">${btn('🌐 Navegador VPS','remote-browser','ghost',`data-id="${p.id}"`)}${btn('↓ Importar dados','remote-browser','primary',`data-id="${p.id}"`)}${!browser&&p.auth_mode!=='remote_browser'?btn('⟳ API','sync-panel','ghost',`data-id="${p.id}"`):''}${btn('↗ Site original','open-panel','ghost',`data-id="${p.id}"`)}<button class="action-dot" title="Editar" data-action="edit-panel" data-id="${p.id}">✎</button><button class="action-dot" title="Remover" data-action="remove-panel" data-id="${p.id}">×</button></div>${p.last_sync?`<p class="helper-text">Última sincronização bem-sucedida: ${esc(p.last_sync)}</p>`:''}</div>`;}).join(''):`<div class="mini-card"><div class="mini-icon">＋</div><h3>Nenhum painel conectado</h3><p>Cadastre URL, usuário e senha para tentar a sincronização por API.</p>${btn('Conectar meu painel','new-panel','primary')}</div>`}</div>
 <div class="callout mt20"><b>Compatibilidade:</b> no modo Chromium, a autenticação acontece em um navegador real da VPS e os dados são lidos da página exibida. Cada painel tem interface própria; o reconhecimento de login, vencimentos e paginação deve ser testado. Desafios Cloudflare e CAPTCHA não são contornados. Se a lista não for reconhecida, a sincronização falha sem alterar clientes.</div>`;
}
function renderPlans(){let plans=state.plans;$('#content').innerHTML=title('CATÁLOGO DE SERVIÇOS','Planos & assinaturas','Padronize preços, periodicidades e cadastro de clientes.',btn('＋ Novo plano','new-plan','primary'))+`<div class="cards-grid">${plans.length?plans.map(p=>`<div class="mini-card" style="border-top:3px solid ${esc(p.color)}"><div class="mini-icon" style="color:${esc(p.color)}">▤</div><h3>${esc(p.name)}</h3><div style="font-size:28px;font-weight:850;letter-spacing:-1px;margin:16px 0">${brl(p.price)}</div><p>${p.days} dias de validade • ${state.clients.filter(c=>c.plan_id===p.id).length} clientes vinculados</p><div class="mini-bottom">${btn('Cadastrar cliente','new-client','ghost',`data-plan="${p.id}"`)}<button class="action-dot" title="Editar plano" data-action="edit-plan" data-id="${p.id}">✎</button><button class="action-dot" title="Excluir plano" data-action="remove-plan" data-id="${p.id}">×</button></div></div>`).join(''):'<div class="empty"><h3>Nenhum plano</h3></div>'}</div>`;}
function renderSettings(){const s=state.settings;$('#content').innerHTML=title('PREFERÊNCIAS','Configurações','Personalize a experiência, os lembretes e a comunicação com seus clientes.')+`<div class="grid-side"><section class="panel-card"><div class="section-row"><div><h2>Identidade & operação</h2><p>Defina suas preferências de trabalho</p></div></div><form id="settings-form" class="stack"><label>Nome da operação<input name="business_name" value="${esc(s.business_name)}" required maxlength="180"></label><label>Dias para lembrar antes do vencimento<input name="reminder_days" value="${esc(s.reminder_days)}" placeholder="7,3,1,0" required></label><label>Mensagem do WhatsApp<textarea name="reminder_template" rows="5">${esc(s.reminder_template)}</textarea></label><p class="helper-text">Variáveis disponíveis: {nome}, {vencimento}, {plano}, {valor}</p><label>Assunto do e-mail<input name="email_subject" value="${esc(s.email_subject)}"></label><label class="flex" style="justify-content:flex-start"><input type="checkbox" name="email_enabled" ${s.email_enabled==='true'?'checked':''} style="width:18px;height:18px;margin:0"> Habilitar lembretes automáticos por e-mail</label><button class="btn primary" type="submit">Salvar configurações</button></form></section><div><section class="panel-card"><div class="section-row"><h2>Segurança</h2></div><div class="statline"><span>Perfil</span><strong>${esc(state.me.role)}</strong></div><div class="statline"><span>Conta</span><strong style="overflow-wrap:anywhere">${esc(state.me.email)}</strong></div><div class="statline"><span>Criptografia</span><strong>Ativada</strong></div><p class="helper-text">Senhas de assinantes e tokens são criptografados. Mantenha a chave privada e backup do banco.</p><div class="divider" style="border-top:1px solid #34405a;margin:20px 0"></div><h3 style="font-size:13px">Alterar minha senha</h3><form id="password-form" class="stack">${input('Senha atual','current_password','','password','required')}${input('Nova senha (mínimo 10 caracteres)','new_password','','password','required minlength="10"')}<button class="btn ghost" type="submit">Atualizar senha</button></form></section><section class="panel-card mt20"><div class="section-row"><h2>E-mail & notificações</h2></div><p class="helper-text">SMTP: ${s.smtp_ready?'Configurado no servidor':'Pendente no servidor'}. O disparo automático requer SMTP válido e processo de lembretes agendado.</p>${btn('Ver vencimentos','go-reminders','ghost')}</section></div></div>`;$('#settings-form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.email_enabled=!!e.target.email_enabled.checked;try{await request('/settings','PUT',d);await afterSave('Configurações salvas');}catch(er){toast(er.message,true);}};$('#password-form').onsubmit=async e=>{e.preventDefault();try{await request('/account/password','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();toast('Senha atualizada. Outras sessões foram encerradas.');}catch(er){toast(er.message,true);}};}
async function renderTeam(){if(!state.staff.length){try{state.staff=(await api('/staff')).staff;}catch(e){$('#content').innerHTML=title('ADMINISTRAÇÃO','Equipe & permissões','Sua conta não tem permissão para visualizar usuários.');return;}}$('#content').innerHTML=title('CONTROLE DE ACESSO','Sua equipe','Crie acessos diferentes e acompanhe os responsáveis pela operação.',state.me.role==='admin'?btn('＋ Novo membro','new-staff','primary'):'')+`<section class="panel-card"><div class="section-row"><h2>Membros da equipe</h2><span class="muted small">${state.staff.length} cadastrados</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Nome</th><th>E-mail</th><th>Permissão</th><th>Adicionado</th></tr></thead><tbody>${state.staff.map((u,i)=>`<tr><td><div class="client-cell">${initials(u.name,i)}<strong>${esc(u.name)}</strong></div></td><td>${esc(u.email)}</td><td><span class="status active">${{admin:'Administrador',manager:'Gerente',operator:'Operador'}[u.role]}</span></td><td>${esc(u.created_at.slice(0,10))}</td></tr>`).join('')}</tbody></table></div></section><div class="callout mt20"><b>Perfis:</b> Administrador cria usuários, gerentes gerenciam clientes, planos e integrações; operadores acompanham e atualizam assinaturas e pagamentos. Ações sensíveis ficam registradas no histórico.</div>`;}
async function renderActivity(){let data=await api('/activity');state.activity=data.activity;$('#content').innerHTML=title('AUDITORIA & SEGURANÇA','Histórico de ações','Acompanhe as principais operações e mudanças feitas por sua equipe.')+`<section class="panel-card"><div class="section-row"><h2>Atividade recente</h2><span class="muted small">${data.activity.length} eventos</span></div>${data.activity.length?data.activity.map(a=>`<div class="activity-row"><span class="activity-dot"></span><div><strong>${esc(a.action.replaceAll('.', ' › '))}</strong><small>${esc(a.actor)} · ${esc(a.detail)}</small></div><time>${esc(a.created_at)}</time></div>`).join(''):`<div class="empty"><h3>Sem atividades registradas</h3></div>`}</section>`;}
function modal(title,html,onSubmit){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').classList.remove('hide');document.body.style.overflow='hidden';let form=$('#modal-form');if(form&&onSubmit){form.onsubmit=async e=>{e.preventDefault();let b=$('button[type=submit]',form);if(b)b.disabled=true;try{await onSubmit(form,Object.fromEntries(new FormData(form)));}catch(error){toast(error.message,true);}finally{if(b)b.disabled=false;}};}}
function closeModal(){if(remoteState.session){const p=remoteState.panelId,session=remoteState.session;remoteState={panelId:null,session:null,busy:false};request('/panels/'+p+'/browser/close','POST',{session}).catch(()=>{});}else remoteState={panelId:null,session:null,busy:false};$('#modal').classList.add('hide');document.body.style.overflow='';$('#modal-body').innerHTML='';}
function foot(label='Salvar alterações'){return `<div class="modal-foot"><button type="button" class="btn ghost" data-action="close-modal">Cancelar</button><button type="submit" class="btn primary">${label} ↗</button></div>`;}
const input=(label,name,val='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(val)}" ${extra}></label>`;
const fieldSelect=(label,name,list,selected,placeholder='Selecione')=>`<label>${label}<select name="${name}"><option value="">${esc(placeholder)}</option>${list.map(o=>`<option value="${esc(o.id)}" ${String(o.id)===String(selected)?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label>`;
function clientModal(c=null,planId=''){const isEdit=!!c,plan=state.plans.find(p=>p.id===planId),item=c||{status:'active',due_date:localPlusDays(30),price:plan?.price||30,plan_id:planId};modal(isEdit?'Editar cliente':'Cadastrar cliente',`<form id="modal-form"><div class="form-grid">${input('Nome completo *','name',item.name,'text','required maxlength="100"')}${input('WhatsApp / telefone','phone',item.phone,'tel','placeholder="(11) 99999-9999"')}${input('Login de acesso','username',item.username,'text','placeholder="usuario123"')}${input(isEdit?'Nova senha (vazio mantém a atual)':'Senha de acesso','password','','password','autocomplete="new-password"')}${input('E-mail (opcional)','email',item.email,'email')}${input('Data de vencimento *','due_date',item.due_date,'date','required')}${fieldSelect('Plano de assinatura','plan_id',state.plans,item.plan_id,'Personalizado')}${input('Valor da assinatura (R$)','price',item.price,'number','min="0" step="0.01"')}${fieldSelect('Painel de origem','panel_id',state.panels,item.panel_id,'Nenhum painel')}<label>Status<select name="status">${[['active','Ativo'],['trial','Teste'],['paused','Pausado'],['canceled','Cancelado']].map(([v,l])=>`<option value="${v}" ${item.status===v?'selected':''}>${l}</option>`).join('')}</select></label>${input('Dispositivo / aplicativo','device',item.device,'text','placeholder="Smart TV, Android, PC..."')}${input('Tags (separadas por vírgula)','tags',item.tags,'text','placeholder="VIP, indicação, família"')}<label class="wide">Anotações<textarea name="notes" rows="4" placeholder="Detalhes importantes sobre o cliente...">${esc(item.notes)}</textarea></label></div>${isEdit?`<div class="inline-notice">Para consultar a senha atual, use o botão abaixo. A ação será registrada no histórico.<br><button type="button" class="btn sm ghost mt20" data-action="reveal-secret" data-id="${item.id}">◉ Exibir senha de acesso</button><span id="secret-text" style="margin-left:12px;overflow-wrap:anywhere"></span></div>`:''}${isEdit?`<button type="button" class="btn sm danger mt20" data-action="archive-client" data-id="${item.id}">Arquivar cliente</button>`:''}${foot(isEdit?'Salvar cliente':'Criar cliente')}</form>`,async(f,d)=>{await request(isEdit?'/clients/'+c.id:'/clients',isEdit?'PUT':'POST',d);closeModal();await afterSave(isEdit?'Cadastro atualizado':'Cliente adicionado com sucesso');});$('#modal-form select[name=plan_id]').onchange=e=>{let p=state.plans.find(x=>x.id===e.target.value);if(p){$('#modal-form input[name=price]').value=p.price;if(!isEdit)$('#modal-form input[name=due_date]').value=localPlusDays(p.days);}};}
function renewModal(c){let plan=state.plans.find(p=>p.id===c.plan_id);modal('Renovar assinatura',`<div class="inline-notice"><strong>${esc(c.name)}</strong> · ${esc(c.username||'Sem login')}<br>Vencimento atual: ${fdate(c.due_date)} · ${smallDue(c)}</div><form id="modal-form"><div class="form-grid">${input('Dias de renovação','days',plan?.days||30,'number','required min="1" max="730"')}${input('Valor recebido (R$)','amount',c.price,'number','min="0" step="0.01" required')}<label class="wide">Forma de pagamento<select name="method"><option value="pix">Pix</option><option value="cash">Dinheiro</option><option value="card">Cartão</option><option value="other">Outro</option></select></label><label class="wide" style="display:flex;align-items:center;gap:9px"><input type="checkbox" name="record_payment" checked style="width:16px;height:16px;margin:0"> Registrar recebimento no financeiro</label></div>${foot('Confirmar renovação')}</form>`,async(f,d)=>{d.record_payment=!!f.record_payment.checked;await request('/clients/'+c.id+'/renew','POST',d);closeModal();await afterSave('Assinatura renovada com sucesso');});}
function paymentModal(){modal('Registrar pagamento',`<form id="modal-form"><div class="form-grid">${fieldSelect('Cliente *','client_id',state.clients.map(c=>({id:c.id,name:c.name+' · '+c.username})),'','Escolha um cliente')}${input('Valor (R$) *','amount','30','number','required min="0" step="0.01"')}<label>Forma de pagamento<select name="method"><option value="pix">Pix</option><option value="cash">Dinheiro</option><option value="card">Cartão</option><option value="other">Outro</option></select></label>${input('Data do recebimento *','paid_at',localISO(),'date','required')}<div class="wide">${input('Descrição','description','','text','placeholder="Ex.: Mensalidade novembro"')}</div></div><p class="helper-text">O lançamento financeiro não altera automaticamente o vencimento. Use “Renovar” no cadastro para atualizar a assinatura e registrar o recebimento juntos.</p>${foot('Registrar recebimento')}</form>`,async(f,d)=>{await request('/payments','POST',d);closeModal();await afterSave('Pagamento registrado');});}
function panelModal(panel=null){
 const p=panel||{},editing=!!panel,mode=p.auth_mode||'remote_browser';
 modal(editing?'Editar conexão do painel':'Conectar painel por URL, usuário e senha',
 `<form id="modal-form"><div class="form-grid">
 ${input('Nome da conexão *','name',p.name,'text','required placeholder="Painel principal"')}
 <label>Tipo de painel<select name="kind"><option value="sigma" ${p.kind==='sigma'?'selected':''}>Sigma</option><option value="painelfoda" ${p.kind==='painelfoda'?'selected':''}>PainelFoda</option><option value="xtream" ${p.kind==='xtream'?'selected':''}>Xtream / XUI</option><option value="custom" ${p.kind==='custom'?'selected':''}>Outro</option></select></label>
 <div class="wide">${input('URL HTTPS do seu painel *','url',p.url,'url','required placeholder="https://meu-painel.exemplo.com"')}</div>
 ${input('Usuário do painel','login_user',p.login_user,'text','autocomplete="username" placeholder="Seu login de revenda"')}
 ${input(editing?'Senha (vazio mantém a atual)':'Senha do painel','login_pass','','password','autocomplete="new-password" placeholder="Senha do painel"')}
 <label class="wide" style="display:flex;align-items:center;gap:10px"><input type="checkbox" name="auto_sync" ${editing&&p.auto_sync?'checked':''} style="width:17px;height:17px;margin:0"> Habilitar sincronização agendada (requer agendador externo configurado)</label>
 </div>
 <details style="margin:16px 0"><summary style="cursor:pointer;color:#afa7ff">Configurações avançadas de integração (API)</summary><div class="form-grid mt20"><label>Modo de autenticação<select name="auth_mode" id="panel-auth-mode"><option value="remote_browser" ${mode==='remote_browser'?'selected':''}>Navegador Chromium na VPS (sem API)</option><option value="credentials" ${mode==='credentials'?'selected':''}>URL, usuário e senha (API autorizada)</option><option value="browser" ${mode==='browser'?'selected':''}>Apenas abrir no navegador (sem sincronizar)</option><option value="token" ${mode==='token'?'selected':''}>Token de API autorizado</option></select></label><div></div>
 <div class="wide">${input('Rota de autenticação','login_path',p.login_path||'/api/login','text','placeholder="/api/login"')}</div>
 <div class="wide">${input('Rota de clientes','clients_path',p.clients_path||'/api/clients','text','placeholder="/api/clients"')}</div>
 <div class="wide">${input('Rota de planos','plans_path',p.plans_path??'/api/plans','text','placeholder="/api/plans"')}</div>
 ${input('Nome do campo de usuário (JSON)','login_field',p.login_field||'username','text')}
 ${input('Nome do campo de senha (JSON)','password_field',p.password_field||'password','text')}
 <div class="wide">${input('Endpoint da API com token (modo opcional)','api_url',p.api_url||'','url','placeholder="https://api.exemplo.com/clientes"')}</div>
 <div class="wide">${input(editing?'Novo token (vazio mantém o atual)':'Token autorizado da API','token','','password')}</div></div></details>
 <div class="inline-notice"><b>Navegador real na VPS:</b> o Clystria abre Chromium no servidor, usa as credenciais já salvas e tenta ler os clientes exibidos na interface do fornecedor. Uma sessão isolada é fechada após cada consulta. Não usa extensão, WebView nem API pública. Este modo é experimental: Cloudflare/CAPTCHA não são burlados e cada layout pode exigir adaptação própria.</div>
 ${foot('Salvar conexão')}</form>`,async(f,d)=>{
 d.auto_sync=d.auth_mode!=='browser'&&!!f.elements.auto_sync.checked;
 if(d.auth_mode==='browser'){d.login_pass='';d.token='';}
 const result=await request(editing?'/panels/'+p.id:'/panels',editing?'PUT':'POST',d);
 const id=editing?p.id:result.id;
 let message='Configuração salva, aguardando validação do conector.';
 if(d.auth_mode==='browser'){message='Conexão salva para login no Safari/Chrome. Acesse o painel e importe o arquivo exportado.';}else{try{let r=await request('/panels/'+id+'/sync','POST',{});message=`Conectado: ${r.created} novos clientes, ${r.updated} atualizados, ${r.plans_created} planos`+(r.warning?' · '+r.warning:'');}catch(e){message='Conexão salva, mas a API não sincronizou: '+e.message;}}
 closeModal();await afterSave(message);
 });
}
function planModal(p=null){modal(p?'Editar plano':'Criar plano',`<form id="modal-form"><div class="form-grid">${input('Nome do plano *','name',p?.name||'','text','required placeholder="Premium Mensal"')}${input('Periodicidade (dias) *','days',p?.days||30,'number','required min="1" max="730"')}${input('Preço (R$)','price',p?.price??30,'number','min="0" step="0.01"')}<label>Cor de identificação<input type="color" name="color" value="${esc(p?.color||'#786CFF')}" style="height:43px;padding:6px"></label></div>${foot(p?'Salvar plano':'Cadastrar plano')}</form>`,async(f,d)=>{await request(p?'/plans/'+p.id:'/plans',p?'PUT':'POST',d);closeModal();await afterSave(p?'Plano atualizado':'Plano adicionado');});}
function teamModal(){modal('Novo membro da equipe',`<form id="modal-form"><div class="form-grid">${input('Nome *','name','','text','required')}${input('E-mail *','email','','email','required')}${input('Senha provisória (10+ caracteres) *','password','','password','required minlength="10"')}<label>Permissão<select name="role"><option value="operator">Operador</option><option value="manager">Gerente</option></select></label></div><p class="helper-text">Forneça a senha ao membro por um canal seguro. Oriente-o a não compartilhá-la.</p>${foot('Criar acesso')}</form>`,async(f,d)=>{await request('/staff','POST',d);state.staff=[];closeModal();await afterSave('Acesso da equipe criado');});}
function importModal(panelId=''){
 const selected=state.panels.find(p=>p.id===panelId);
 const titleText=selected?'Importar clientes — '+selected.name:'Importar clientes do painel';
 modal(titleText,`<form id="modal-form">
 <p class="helper-text"><b>1.</b> Abra o painel original no Safari ou Chrome e faça login por lá.<br><b>2.</b> Use a função Exportar/CSV/Excel do fornecedor, quando disponível.<br><b>3.</b> Selecione o arquivo aqui. O Clystria não lê cookies nem senhas do outro site.</p>
 <label>Arquivo exportado (.csv, .tsv ou .json)<input id="csv-file" type="file" accept=".csv,.tsv,.txt,.json,text/csv,text/tab-separated-values,application/json" style="padding:10px"></label>
 <p class="helper-text">Colunas aceitas: nome, telefone, email, login, status, vencimento, plano, valor. Vencimento precisa ser fornecido pelo painel. Também é possível colar CSV ou TSV abaixo.</p>
 <label>Prévia dos dados para importar<textarea name="csv" id="csv-text" rows="6" placeholder="nome,telefone,login,status,vencimento,valor&#10;Exemplo,11999999999,exemplo,active,2026-12-21,30"></textarea></label>
 ${fieldSelect('Vincular a qual painel?','panel_id',state.panels,panelId,'Sem painel')}
 <label class="flex" style="justify-content:flex-start"><input type="checkbox" name="upsert" ${panelId?'checked':''} style="width:18px;height:18px;margin:0"> Atualizar clientes já importados deste painel pelo login (não duplicar)</label>
 ${foot('Importar clientes')}</form>`,async(f,d)=>{
   if(!d.csv.trim())throw Error('Escolha um arquivo exportado ou cole os dados.');
   d.upsert=!!f.elements.upsert.checked;
   const r=await request('/import/clients','POST',d);
   closeModal();
   await afterSave(`${r.created} novos, ${r.updated||0} atualizados e ${r.ignored} ignorados (${r.total} linhas)`);
 });
 $('#csv-file').onchange=async e=>{
  let file=e.target.files?.[0];if(!file)return;
  if(file.size>1000000){toast('Arquivo acima de 1 MB. Divida a exportação em partes.',true);return;}
  try{
   let s=await file.text();
   if(/\\.json$/i.test(file.name)||s.trimStart().startsWith('{')||s.trimStart().startsWith('[')){
    const parsed=JSON.parse(s);
    const candidates=[parsed,parsed?.clients,parsed?.users,parsed?.data?.clients,parsed?.data?.users,parsed?.data?.items];
    const rows=candidates.find(Array.isArray);
    if(!rows)throw Error('JSON não contém uma lista de clientes reconhecível');
    const keys=['nome','telefone','email','login','senha','status','vencimento','plano','valor'];
    const first=(o,aliases)=>aliases.map(k=>o?.[k]).find(v=>v!==undefined&&v!==null&&v!=='')??'';
    const fields=[['name','nome','cliente','full_name'],['phone','telefone','whatsapp','mobile'],['email'],['username','login','usuario','user'],['password','senha'],['status','situacao'],['due_date','vencimento','expiration','expires_at','expire_at'],['plan_name','plano','package_name'],['price','valor']];
    const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';
    s=keys.join(',')+'\\n'+rows.map(o=>fields.map(field=>quote(first(o,field))).join(',')).join('\\n');
   }
   $('#csv-text').value=s;
  }catch(ex){toast('Não foi possível ler o arquivo: '+ex.message,true);}
 };
}

function remoteFrame(frame){
 if(!frame||!frame.ok||!String(frame.screen||'').startsWith('data:image/jpeg;base64,'))throw Error('A VPS não retornou uma imagem válida do navegador');
 remoteState.session=frame.session;
 const img=$('#remote-shot');
 if(img)img.src=frame.screen;
 if($('#remote-url'))$('#remote-url').textContent=frame.url||'Página do fornecedor';
 if($('#remote-status'))$('#remote-status').textContent='Sessão conectada • toque na tela para clicar';
}
async function remoteStep(kind,data={}){
 if(remoteState.busy||!remoteState.session)return;
 const panelId=remoteState.panelId,session=remoteState.session;
 remoteState.busy=true;
 if($('#remote-status'))$('#remote-status').textContent='Processando no navegador da VPS...';
 try{
  if(kind==='import'){
   const r=await request('/panels/'+panelId+'/browser/import','POST',{session});
   toast('Importação concluída: '+r.created+' novos, '+r.updated+' atualizados, '+r.ignored+' ignorados');
   await refresh();
   if($('#remote-status'))$('#remote-status').textContent='Dados importados com sucesso';
  }else{
   const path=kind==='frame'?'frame':'action';
   const result=await request('/panels/'+panelId+'/browser/'+path,'POST',{session,...(kind==='frame'?{}:{action:kind,...data})});
   if(remoteState.panelId===panelId)remoteFrame(result);
  }
 }catch(e){
  if($('#remote-status'))$('#remote-status').textContent='Falha: '+e.message;
  toast(e.message,true);
 }finally{remoteState.busy=false;}
}
async function openRemoteBrowser(panelId){
 const panel=state.panels.find(p=>p.id===panelId);
 if(!panel)return toast('Conexão não encontrada',true);
 if(remoteState.session)closeModal();
 remoteState={panelId,session:null,busy:true};
 const html='<div class="remote-browser">'+
 '<div class="remote-top"><span id="remote-url">Conectando ao navegador Chromium...</span><span id="remote-status">Abrindo a sessão na VPS</span></div>'+
 '<div class="remote-screen"><img id="remote-shot" alt="Tela remota do navegador Chromium" draggable="false"><span class="remote-wait">A tela do navegador será exibida aqui.</span></div>'+
 '<div class="remote-controls">'+
 '<button type="button" class="btn ghost" id="remote-refresh">↻ Atualizar tela</button>'+
 '<button type="button" class="btn ghost" id="remote-reload">↻ Recarregar site</button>'+
 '<button type="button" class="btn ghost" id="remote-autofill">✦ Preencher login salvo</button>'+
 '<button type="button" class="btn ghost" id="remote-tab">Tab</button>'+
 '<button type="button" class="btn ghost" id="remote-enter">Enter</button>'+
 '<button type="button" class="btn ghost" id="remote-backspace">⌫ Apagar</button>'+
 '<button type="button" class="btn ghost" id="remote-scroll-up">↑ Rolar</button>'+
 '<button type="button" class="btn ghost" id="remote-scroll-down">↓ Rolar</button></div>'+
 '<div class="remote-type"><input id="remote-input" autocomplete="off" placeholder="Digite aqui para o campo selecionado na tela"><button type="button" class="btn ghost" id="remote-type-btn">Digitar</button></div>'+
 '<div class="remote-actions"><button type="button" class="btn primary" id="remote-import">↓ Importar clientes desta página</button>'+
 '<button type="button" class="btn danger" id="remote-finish">Encerrar navegador</button></div>'+
 '<p class="helper-text">Sessão real no Chromium da VPS, controlada por toque ou mouse. Faça login na página do fornecedor. A verificação humana, quando exigida, depende das regras do site; o Clystria não a contorna. Senhas salvas são preenchidas somente após seu comando.</p></div>';
 modal('Navegador VPS — '+panel.name,html);
 const shot=$('#remote-shot');
 shot.onclick=e=>{
  if(!remoteState.session||remoteState.busy)return;
  const box=shot.getBoundingClientRect();
  remoteStep('click',{x:Math.max(0,Math.min(1100,(e.clientX-box.left)*1100/box.width)),
     y:Math.max(0,Math.min(720,(e.clientY-box.top)*720/box.height))});
 };
 $('#remote-refresh').onclick=()=>remoteStep('frame');
 $('#remote-reload').onclick=()=>remoteStep('reload');
 $('#remote-autofill').onclick=()=>remoteStep('autofill');
 $('#remote-tab').onclick=()=>remoteStep('key',{key:'Tab'});
 $('#remote-enter').onclick=()=>remoteStep('key',{key:'Enter'});
 $('#remote-backspace').onclick=()=>remoteStep('key',{key:'Backspace'});
 $('#remote-scroll-up').onclick=()=>remoteStep('scroll',{dy:-550});
 $('#remote-scroll-down').onclick=()=>remoteStep('scroll',{dy:550});
 $('#remote-type-btn').onclick=()=>{let t=$('#remote-input');if(t.value){remoteStep('type',{text:t.value});t.value='';}};
 $('#remote-input').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#remote-type-btn').click();}};
 $('#remote-import').onclick=()=>remoteStep('import');
 $('#remote-finish').onclick=()=>closeModal();
 try{
  const frame=await request('/panels/'+panelId+'/browser/open','POST',{});
  if(remoteState.panelId!==panelId||$('#modal').classList.contains('hide')){
   request('/panels/'+panelId+'/browser/close','POST',{session:frame.session}).catch(()=>{});return;
  }
  remoteFrame(frame);
 }catch(e){if($('#remote-status'))$('#remote-status').textContent='Falha: '+e.message;toast(e.message,true);}
 finally{remoteState.busy=false;}
}

function openPanel(p){try{let u=new URL(p.url);if(!['http:','https:'].includes(u.protocol))throw Error('URL não aceita');window.open(u.href,'_blank','noopener,noreferrer');toast('Painel aberto no navegador. Faça login na página original.');}catch(e){toast(e.message,true);}}
function whatsapp(c){let n=phone(c.phone);if(n.length===10||n.length===11)n='55'+n;if(n.length<12){toast('Informe um WhatsApp válido no cadastro do cliente.',true);return;}let entry=state.reminders.find(r=>r.id===c.id),msg=entry?.message||state.settings.reminder_template.replaceAll('{nome}',c.name).replaceAll('{vencimento}',fdate(c.due_date)).replaceAll('{plano}',c.plan_name||'').replaceAll('{valor}',brl(c.price));window.open('https://wa.me/'+n+'?text='+encodeURIComponent(msg),'_blank','noopener,noreferrer');api('/reminders/mark',{method:'POST',body:JSON.stringify({client_id:c.id,channel:'whatsapp'})}).catch(()=>{});toast('Conversa aberta. Confirme o envio no WhatsApp.');}
async function clickAction(b){let a=b.dataset.action,id=b.dataset.id;try{
if(a==='close-modal')return closeModal();if(a==='new-client')return clientModal(null,b.dataset.plan||'');if(a==='edit-client')return clientModal(state.clients.find(c=>c.id===id));if(a==='renew-client')return renewModal(state.clients.find(c=>c.id===id));if(a==='new-payment')return paymentModal();if(a==='new-panel')return panelModal();if(a==='new-plan')return planModal();if(a==='edit-plan')return planModal(state.plans.find(p=>p.id===id));if(a==='new-staff')return teamModal();if(a==='browser-check'){const result=await api('/browser/status');toast(result.ok?'Chromium em servidor: pronto para tentar a autenticação.':'Chromium ainda não está pronto.',!result.ok);return;}if(a==='import')return importModal();if(a==='browser-import')return openRemoteBrowser(id);if(a==='go-settings')return route('settings');if(a==='go-reminders')return route('reminders');if(a==='export'){window.location.href='/api/export/clients';return toast('Exportação iniciada');}if(a==='whatsapp')return whatsapp(state.clients.find(c=>c.id===id));
if(a==='reveal-secret'){const r=await api('/clients/'+id+'/secret');$('#secret-text').textContent=r.password||'(não cadastrada)';return;}
if(a==='remote-browser')return openRemoteBrowser(id);
if(a==='open-panel')return openPanel(state.panels.find(p=>p.id===id));
if(a==='edit-panel')return panelModal(state.panels.find(p=>p.id===id));
if(a==='sync-panel'){if(state.panels.find(p=>p.id===id)?.auth_mode==='browser'){toast('Modo navegador: importe o arquivo exportado. Para sincronizar automaticamente, configure API autorizada.',true);return;}const label=b.textContent;b.disabled=true;b.textContent='Sincronizando...';try{let r=await request('/panels/'+id+'/sync','POST',{});await afterSave(`Sincronização: ${r.created} novos, ${r.updated} atualizados, ${r.plans_created} planos, ${r.ignored} ignorados`+(r.warning?" · "+r.warning:""));}catch(e){await refresh();route('panels');toast(e.message,true);}finally{b.disabled=false;b.textContent=label;}return;}
if(a==='remove-plan'){if(!confirm('Excluir este plano? Os clientes permanecem cadastrados.'))return;await request('/plans/'+id,'DELETE',{});return afterSave('Plano excluído');}
if(a==='remove-panel'){if(!confirm('Excluir esta conexão? Os clientes permanecem cadastrados.'))return;await request('/panels/'+id,'DELETE',{});return afterSave('Painel removido');}
if(a==='archive-client'){if(!confirm('Arquivar este cliente?'))return;await request('/clients/'+id,'DELETE',{});closeModal();return afterSave('Cliente arquivado');}
}catch(e){toast(e.message,true);}}
document.addEventListener('click',e=>{let v=e.target.closest('[data-view]');if(v){route(v.dataset.view);return;}let filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;renderClients();$('#search').focus();return;}let a=e.target.closest('[data-action]');if(a){clickAction(a);return;}});
$('#auth-form').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target)),mode=e.target.dataset.mode;try{let r=await request(mode==='setup'?'/setup':'/login','POST',data);state.csrf=r.csrf;await enter(await api('/me'));toast('Bem-vindo ao Clystria!');}catch(er){toast(er.message,true);}};
$('#logout').onclick=async()=>{try{await request('/logout','POST',{});}catch{}state.csrf='';state.me=null;showAuth(true);};
$('#top-alert').onclick=()=>route('reminders');$('#go-panels').onclick=()=>route('panels');$('#menu-toggle').onclick=()=>{$('#sidebar').classList.add('open');$('#veil').classList.add('open');};$('#side-close').onclick=$('#veil').onclick=()=>{$('#sidebar').classList.remove('open');$('#veil').classList.remove('open');};$('#modal-close').onclick=closeModal;$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal();};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
boot();


/* Growth management: uses the original Clystria components, colors and navigation. */
const growLabels={new:'Novo',contacted:'Em contato',negotiating:'Negociação',won:'Convertido',lost:'Perdido'};
const growCache={};
function growRow(fields){return '<tr>'+fields.map(x=>'<td>'+x+'</td>').join('')+'</tr>';}
function growTable(head,rows){if(!rows.length)return '<div class="empty"><h3>Nenhum registro</h3><p>Use o botão acima para começar.</p></div>';return '<div class="table-wrap"><table class="data-table"><thead><tr>'+head.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>';}
function growCard(name,sub,body){return '<section class="panel-card mt20"><div class="section-row"><div><h2>'+esc(name)+'</h2><p>'+esc(sub)+'</p></div></div>'+body+'</section>';}
function growAction(label,action,id,kind='ghost'){return btn(label,action,kind,id?'data-id="'+esc(id)+'"':'');}
function growSelect(name,list){return '<label>'+name+'<select name="'+(name==='Cliente'?'client_id':'referrer_id')+'" required><option value="">Selecione...</option>'+list.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+'</option>').join('')+'</select></label>';}
async function growView(page){
 let actions={leads:['Funil comercial','Acompanhe oportunidades e conversões','Novo lead','grow-new-lead'],interactions:['Histórico de atendimentos','Registre o relacionamento com clientes e interessados','Registrar contato','grow-new-interaction'],invoices:['Faturas & cobranças','Contas a receber e baixa de pagamentos','Nova fatura','grow-new-invoice'],campaigns:['Campanhas inteligentes','Mensagens de vencimento e recuperação','Nova campanha','grow-new-campaign'],referrals:['Indique & ganhe','Controle indicações e recompensas','Nova indicação','grow-new-referral'],security:['Autenticação de 2 fatores','Reforce a segurança de sua conta','','']};
 let a=actions[page];$('#content').innerHTML=title('CLYSTRIA GESTÃO',a[0],a[1],a[3]?growAction('＋ '+a[2],a[3],'','primary'):'')+'<section class="panel-card">Carregando...</section>';
 try {
  const d=await api(page==='security'?'/security/2fa':'/crm/'+page);growCache[page]=d;
  let content='';
  if(page==='leads'){
   const stages=['new','contacted','negotiating','won','lost'];
   content='<div class="cards-grid">'+stages.map(stage=>{let items=d.leads.filter(x=>x.stage===stage);return '<div class="mini-card"><div class="flex"><h3>'+growLabels[stage]+'</h3><span class="status trial">'+items.length+'</span></div>'+items.map(l=>'<div class="statline"><div style="flex:1"><strong>'+esc(l.name)+'</strong><small style="display:block">'+esc(l.phone||l.email)+' · '+brl(l.value_cents/100)+'</small></div>'+growAction('↗','grow-next-lead',l.id)+'</div>').join('')+'</div>';}).join('')+'</div>';
  }
  if(page==='interactions')content=growCard('Atendimentos recentes','Histórico auditável',growTable(['Cliente ou lead','Canal','Atendimento','Responsável'],d.interactions.map(i=>growRow([esc(i.client_name||i.lead_name||'—'),esc(i.channel),esc(i.message),esc(i.actor)]))));
  if(page==='invoices'){
   const pending=d.invoices.filter(x=>x.status==='pending');content='<div class="grid4"><div class="kpi-card featured"><div class="kpi-top">A receber</div><strong>'+brl(pending.reduce((s,x)=>s+Number(x.amount_cents),0)/100)+'</strong><div class="kpi-foot">'+pending.length+' faturas pendentes</div></div><div class="kpi-card"><div class="kpi-top">Recebidas</div><strong>'+d.invoices.filter(x=>x.status==='paid').length+'</strong></div></div>';
   content+=growCard('Todas as faturas','Confirme o pagamento apenas após verificar o recebimento',growTable(['Cliente','Valor','Vencimento','Situação','Ação'],d.invoices.map(i=>growRow([esc(i.client_name),brl(i.amount_cents/100),fdate(i.due_date),esc(i.status),i.status==='pending'?growAction('Confirmar pagamento','grow-paid',i.id,'mint'):'✓']))));
   content+='<div class="callout mt20"><b>Pagamento:</b> a baixa atual é manual. Integração PIX automática exige gateway e webhook verificados.</div>';
  }
  if(page==='campaigns'){
   content='<div class="cards-grid">'+d.campaigns.map(c=>'<div class="mini-card"><div class="mini-icon">✉</div><h3>'+esc(c.title)+'</h3><p>'+esc(c.template)+'</p><p>'+esc(c.channel)+' · '+c.days_offset+' dias antes do vencimento</p>'+growAction(c.enabled?'Pausar':'Ativar','grow-toggle-campaign',c.id)+'</div>').join('')+'</div>';
   content+=growCard('Fila de comunicações','Mensagens programadas aguardando integração autorizada',growTable(['Cliente','Canal','Situação'],d.queue.map(q=>growRow([esc(q.client_name),esc(q.channel),esc(q.status)]))));
  }
  if(page==='referrals')content=growCard('Indicações cadastradas','Controle de origem e valor previsto',growTable(['Indicou','Novo cliente','Bônus','Situação'],d.referrals.map(r=>growRow([esc(r.referrer_name),esc(r.referred_name),brl(r.bonus_cents/100),esc(r.status)]))));
  if(page==='security')content=growCard('Autenticação TOTP','Use aplicativo autenticador compatível',d.enabled?'<p>Autenticação de dois fatores <b>ativada</b>.</p>'+growAction('Desativar 2FA','grow-disable-2fa'):'<p>Ative para proteger sua conta com um código de 6 dígitos no login.</p>'+growAction('Ativar 2FA','grow-enable-2fa','','primary'));
  $('#content').innerHTML=title('CLYSTRIA GESTÃO',a[0],a[1],a[3]?growAction('＋ '+a[2],a[3],'','primary'):'')+content;
 }catch(e){toast(e.message,true);$('#content').innerHTML=title('CLYSTRIA GESTÃO','Não foi possível carregar',e.message);}
}
async function growClick(b){
 const action=b.dataset.action, id=b.dataset.id, list=(state.clients||[]);
 try {
  if(action==='grow-new-lead')return modal('Novo interessado','<form id="modal-form"><div class="form-grid">'+input('Nome *','name','','text','required')+input('WhatsApp','phone','','tel')+input('E-mail','email','','email')+input('Origem','source')+input('Valor potencial R$','value',0,'number','min="0" step="0.01"')+'<label>Etapa<select name="stage">'+Object.keys(growLabels).map(k=>'<option value="'+k+'">'+growLabels[k]+'</option>').join('')+'</select></label></div>'+foot('Criar lead')+'</form>',async(f,d)=>{await request('/crm/leads','POST',d);closeModal();growView('leads');});
  if(action==='grow-next-lead'){const l=growCache.leads.leads.find(x=>x.id===id);const steps=['new','contacted','negotiating','won'];let to=steps[steps.indexOf(l.stage)+1]||'contacted';await request('/crm/leads/'+id,'PUT',{stage:to});return growView('leads');}
  if(action==='grow-new-interaction'){const leads=(await api('/crm/leads')).leads;let options=(list.map(c=>'<option value="c:'+c.id+'">'+esc(c.name)+'</option>').concat(leads.map(l=>'<option value="l:'+l.id+'">'+esc(l.name)+' (lead)</option>'))).join('');return modal('Registrar atendimento','<form id="modal-form"><div class="form-grid"><label class="wide">Contato<select name="contact" required><option value="">Selecione...</option>'+options+'</select></label><label>Canal<select name="channel"><option value="whatsapp">WhatsApp</option><option value="telefone">Telefone</option><option value="email">E-mail</option><option value="note">Anotação</option></select></label><label class="wide">Anotação<textarea name="message" required></textarea></label></div>'+foot('Registrar')+'</form>',async(f,d)=>{const [kind,x]=d.contact.split(':');delete d.contact;d[kind==='c'?'client_id':'lead_id']=x;await request('/crm/interactions','POST',d);closeModal();growView('interactions');});}
  if(action==='grow-new-invoice')return modal('Gerar fatura','<form id="modal-form"><div class="form-grid">'+growSelect('Cliente',list)+input('Valor R$','amount','30','number','min="0.01" step="0.01" required')+input('Vencimento','due_date',localPlusDays(3),'date','required')+'</div>'+foot('Gerar fatura')+'</form>',async(f,d)=>{await request('/crm/invoices','POST',d);closeModal();growView('invoices');});
  if(action==='grow-paid'){if(!confirm('Confirma que recebeu esse pagamento? A assinatura vinculada poderá ser renovada.'))return;await request('/crm/invoices/'+id+'/paid','POST',{});await refresh();return growView('invoices');}
  if(action==='grow-new-campaign')return modal('Nova campanha','<form id="modal-form"><div class="form-grid">'+input('Nome da campanha','title','','text','required')+'<label>Canal<select name="channel"><option value="whatsapp">WhatsApp oficial</option><option value="email">E-mail</option></select></label>'+input('Dias de antecedência','days_offset','3','number','min="-180" max="180" required')+'<label>Ativar<select name="enabled"><option value="0">Não</option><option value="1">Sim</option></select></label><label class="wide">Mensagem<textarea name="template" required>Olá, {nome}! Sua assinatura vence em {vencimento}.</textarea></label></div><p class="helper-text">O envio depende de opt-in e API configurada.</p>'+foot('Salvar campanha')+'</form>',async(f,d)=>{await request('/crm/campaigns','POST',d);closeModal();growView('campaigns');});
  if(action==='grow-toggle-campaign'){await request('/crm/campaigns/'+id+'/toggle','POST',{});return growView('campaigns');}
  if(action==='grow-new-referral')return modal('Nova indicação','<form id="modal-form"><div class="form-grid">'+growSelect('Indicador',list).replace('name="referrer_id"','name="referrer_id"')+'<label>Novo cliente<select name="client_id" required><option value="">Selecione...</option>'+list.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('')+'</select></label>'+input('Bônus previsto R$','bonus',0,'number','min="0" step="0.01"')+'</div>'+foot('Registrar indicação')+'</form>',async(f,d)=>{await request('/crm/referrals','POST',d);closeModal();growView('referrals');});
  if(action==='grow-consent'){const v=(await api('/crm/consent/'+id)).consent;return modal('Autorização de mensagens','<form id="modal-form"><p class="helper-text">Confirme somente consentimentos realmente concedidos pelo cliente.</p><label><input type="checkbox" name="whatsapp_opt_in" '+(v.whatsapp_opt_in?'checked':'')+'> Autorizou WhatsApp</label><label><input type="checkbox" name="email_opt_in" '+(v.email_opt_in?'checked':'')+'> Autorizou e-mail</label>'+foot('Salvar')+'</form>',async(f,d)=>{await request('/crm/consent/'+id,'PUT',{whatsapp_opt_in:f.whatsapp_opt_in.checked,email_opt_in:f.email_opt_in.checked});closeModal();toast('Preferências salvas');});}
  if(action==='grow-enable-2fa'){let v=await request('/security/2fa/start','POST',{});return modal('Ativar autenticação','<p class="helper-text">Adicione a chave no seu aplicativo autenticador. Guarde em local seguro.</p><div class="inline-notice">'+esc(v.secret)+'</div><form id="modal-form">'+input('Código de 6 dígitos','code','','text','pattern="[0-9]{6}" required')+foot('Confirmar')+'</form>',async(f,d)=>{await request('/security/2fa/confirm','POST',d);closeModal();growView('security');});}
  if(action==='grow-disable-2fa')return modal('Desativar 2FA','<form id="modal-form">'+input('Senha atual','password','','password','required')+input('Código de 6 dígitos','code','','text','pattern="[0-9]{6}" required')+foot('Desativar')+'</form>',async(f,d)=>{await request('/security/2fa/disable','POST',d);closeModal();growView('security');});
 }catch(e){toast(e.message,true);}
}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action^="grow-"]');if(b)growClick(b);});
